.xt-text:nth-of-type(18) { padding: 5px 15px 10px !important; font-size: 13px !important; color: #999999 !important; cursor: pointer !important; font-weight: 600 !important; }
.xt-text:nth-of-type(18)::after {
    content: "被发现了...好爱你好爱你好爱你...请尽情查阅我的心声吧！" !important; display: block !important; color: #d4e2f0 !important; font-weight: 800 !important;
    opacity: 0 !important; transition: 0.3s !important; margin-top: 8px !important; height: 0 !important; overflow: hidden !important;
