.xt-text:nth-of-type(18):active::after { opacity: 1 !important; height: auto !important; padding-bottom: 10px !important; }

/* 19: iTime */
.xt-text:nth-of-type(19) { padding: 0 15px 30px !important; font-size: 11px !important; color: #999999 !important; letter-spacing: 0.5px !important; }

